use ferro_core::Tensor;
fn tracked(values: &[f32], shape: &[usize]) -> Tensor { Tensor::from_vec(values.to_vec(),shape).unwrap().requires_grad_(true).unwrap() }
fn close(actual: &Tensor, expected: &[f32]) {
    assert_eq!(actual.numel(),expected.len());
    for (&a,&b) in actual.to_vec().iter().zip(expected) { assert!((a-b).abs()<=3e-6*b.abs().max(1.), "{a} != {b}"); }
}

#[test]
fn public_channel_prelu_first_second_third_match_torch_layout_0() {
    let base=tracked(&[-0.699999988079071f32,1.2000000476837158f32,-1.100000023841858f32,0.30000001192092896f32,0.800000011920929f32,-0.4000000059604645f32,1.2999999523162842f32,-0.20000000298023224f32,0.5f32,-1.2000000476837158f32,0.6000000238418579f32,-0.8999999761581421f32],&[2, 3, 2]);
    let g=tracked(&[0.20000000298023224f32,0.30000001192092896f32,0.3999999761581421f32,0.5f32,0.5999999642372131f32,0.699999988079071f32,0.7999999523162842f32,0.8999999761581421f32,1.0f32,1.0999999046325684f32,1.1999999284744263f32,1.2999999523162842f32],&[2, 3, 2]);
    let w=tracked(&[0.20000000298023224f32,-0.30000001192092896f32,0.4000000059604645f32],&[3]);
    let a=tracked(&[-0.6000000238418579f32,-0.5f32,-0.40000003576278687f32,-0.30000001192092896f32,-0.20000001788139343f32,-0.10000001639127731f32,-7.450580596923828e-09f32,0.09999999403953552f32,0.19999998807907104f32,0.30000001192092896f32,0.4000000059604645f32,0.5f32],&[2, 3, 2]);
    let b=tracked(&[-0.20000000298023224f32,0.30000001192092896f32,0.699999988079071f32],&[3]);
    let x=base;
    let y=x.prelu(&w).unwrap();
    let first=y.vjp_wrt_optional(&[&x,&w],&g,true).unwrap();
    close(first[0].as_ref().unwrap(),&[0.04000000283122063f32,0.30000001192092896f32,-0.11999999731779099f32,0.5f32,0.5999999642372131f32,0.2800000011920929f32,0.7999999523162842f32,0.17999999225139618f32,1.0f32,-0.32999998331069946f32,1.1999999284744263f32,0.5199999809265137f32]);
    assert_eq!(first[0].as_ref().unwrap().requires_grad(),true);
    close(first[1].as_ref().unwrap(),&[-0.3199999928474426f32,-1.7599999904632568f32,-1.4499999284744263f32]);
    assert_eq!(first[1].as_ref().unwrap().requires_grad(),true);
    let energy=first[0].as_ref().unwrap().mul(&a).unwrap().sum().add(&first[1].as_ref().unwrap().mul(&b).unwrap().sum()).unwrap();
    let second=energy.vjp_wrt_optional(&[&g,&x,&w,&a,&b],&Tensor::scalar(1.),true).unwrap();
    close(second[0].as_ref().unwrap(),&[0.019999995827674866f32,-0.5f32,-0.21000000834465027f32,-0.30000001192092896f32,-0.20000001788139343f32,-0.3199999928474426f32,-7.450580596923828e-09f32,0.06000000238418579f32,0.19999998807907104f32,-0.45000001788139343f32,0.4000000059604645f32,-0.4300000071525574f32]);
    assert_eq!(second[0].as_ref().unwrap().requires_grad(),true);
    close(second[1].as_ref().unwrap(),&[-0.04000000283122063f32,0.0f32,0.11999999731779099f32,0.0f32,0.0f32,0.4899999797344208f32,0.0f32,-0.17999999225139618f32,0.0f32,0.32999998331069946f32,0.0f32,0.9099999666213989f32]);
    assert_eq!(second[1].as_ref().unwrap().requires_grad(),true);
    close(second[2].as_ref().unwrap(),&[-0.03000001609325409f32,0.16999997198581696f32,0.5799999833106995f32]);
    assert_eq!(second[2].as_ref().unwrap().requires_grad(),true);
    close(second[3].as_ref().unwrap(),&[0.04000000283122063f32,0.30000001192092896f32,-0.11999999731779099f32,0.5f32,0.5999999642372131f32,0.2800000011920929f32,0.7999999523162842f32,0.17999999225139618f32,1.0f32,-0.32999998331069946f32,1.1999999284744263f32,0.5199999809265137f32]);
    assert_eq!(second[3].as_ref().unwrap().requires_grad(),true);
    close(second[4].as_ref().unwrap(),&[-0.3199999928474426f32,-1.7599999904632568f32,-1.4499999284744263f32]);
    assert_eq!(second[4].as_ref().unwrap().requires_grad(),true);
    let mut total=second[0].as_ref().unwrap().sum();
    for derivative in &second[1..] {total=total.add(&derivative.as_ref().unwrap().sum()).unwrap();}
    let third=total.vjp_wrt_optional(&[&g,&x,&w,&a,&b],&Tensor::scalar(1.),false).unwrap();
    close(third[0].as_ref().unwrap(),&[-1.2999999523162842f32,1.0f32,-1.5000001192092896f32,1.0f32,1.0f32,0.5999999642372131f32,1.0f32,-0.10000000894069672f32,1.0f32,-0.8999999761581421f32,1.0f32,0.7000000476837158f32]);
    close(third[1].as_ref().unwrap(),&[0.0f32,0.0f32,0.699999988079071f32,0.0f32,0.0f32,1.399999976158142f32,0.0f32,0.699999988079071f32,0.0f32,1.3999998569488525f32,0.0f32,2.0f32]);
    close(third[2].as_ref().unwrap(),&[0.6000000238418579f32,1.3999998569488525f32,2.4000000953674316f32]);
    close(third[3].as_ref().unwrap(),&[0.4000000059604645f32,1.0f32,0.09999996423721313f32,1.0f32,1.0f32,1.100000023841858f32,1.0f32,1.100000023841858f32,1.0f32,0.7999998927116394f32,1.0f32,1.6999999284744263f32]);
    close(third[4].as_ref().unwrap(),&[0.19999998807907104f32,-0.8000001907348633f32,0.6999999284744263f32]);
    assert!(g.grad().is_none()&&x.grad().is_none()&&w.grad().is_none()&&a.grad().is_none()&&b.grad().is_none());
}

#[test]
fn public_channel_prelu_first_second_third_match_torch_layout_1() {
    let base=tracked(&[-0.699999988079071f32,1.2000000476837158f32,-1.100000023841858f32,0.30000001192092896f32,0.800000011920929f32,-0.4000000059604645f32,1.2999999523162842f32,-0.20000000298023224f32,0.5f32,-1.2000000476837158f32,0.6000000238418579f32,-0.8999999761581421f32],&[2, 3, 2]);
    let g=tracked(&[0.20000000298023224f32,0.30000001192092896f32,0.3999999761581421f32,0.5f32,0.5999999642372131f32,0.699999988079071f32,0.7999999523162842f32,0.8999999761581421f32,1.0f32,1.0999999046325684f32,1.1999999284744263f32,1.2999999523162842f32],&[2, 3, 2]);
    let w=tracked(&[0.20000000298023224f32,-0.30000001192092896f32,0.4000000059604645f32],&[3]);
    let a=tracked(&[-0.6000000238418579f32,-0.5f32,-0.40000003576278687f32,-0.30000001192092896f32,-0.20000001788139343f32,-0.10000001639127731f32,-7.450580596923828e-09f32,0.09999999403953552f32,0.19999998807907104f32,0.30000001192092896f32,0.4000000059604645f32,0.5f32],&[2, 3, 2]);
    let b=tracked(&[-0.20000000298023224f32,0.30000001192092896f32,0.699999988079071f32],&[3]);
    let x=base.transpose(0,2).unwrap();
    let y=x.prelu(&w).unwrap();
    let first=y.vjp_wrt_optional(&[&x,&w],&g,true).unwrap();
    close(first[0].as_ref().unwrap(),&[0.04000000283122063f32,0.30000001192092896f32,-0.11999999731779099f32,0.5f32,0.5999999642372131f32,0.699999988079071f32,0.7999999523162842f32,0.17999999225139618f32,1.0f32,-0.32999998331069946f32,0.47999998927116394f32,0.5199999809265137f32]);
    assert_eq!(first[0].as_ref().unwrap().requires_grad(),true);
    close(first[1].as_ref().unwrap(),&[-0.3199999928474426f32,-1.7599999904632568f32,-1.649999976158142f32]);
    assert_eq!(first[1].as_ref().unwrap().requires_grad(),true);
    let energy=first[0].as_ref().unwrap().mul(&a).unwrap().sum().add(&first[1].as_ref().unwrap().mul(&b).unwrap().sum()).unwrap();
    let second=energy.vjp_wrt_optional(&[&g,&x,&w,&a,&b],&Tensor::scalar(1.),true).unwrap();
    close(second[0].as_ref().unwrap(),&[0.019999995827674866f32,-0.5f32,-0.21000000834465027f32,-0.30000001192092896f32,-0.20000001788139343f32,-0.10000001639127731f32,-7.450580596923828e-09f32,0.06000000238418579f32,0.19999998807907104f32,-0.45000001788139343f32,-0.11999998986721039f32,-0.4300000071525574f32]);
    assert_eq!(second[0].as_ref().unwrap().requires_grad(),true);
    close(second[1].as_ref().unwrap(),&[-0.04000000283122063f32,0.0f32,0.11999999731779099f32,0.0f32,0.0f32,0.0f32,0.0f32,-0.17999999225139618f32,0.0f32,0.32999998331069946f32,0.8399999141693115f32,0.9099999666213989f32]);
    assert_eq!(second[1].as_ref().unwrap().requires_grad(),true);
    close(second[2].as_ref().unwrap(),&[-0.03000001609325409f32,0.16999997198581696f32,1.1299999952316284f32]);
    assert_eq!(second[2].as_ref().unwrap().requires_grad(),true);
    close(second[3].as_ref().unwrap(),&[0.04000000283122063f32,0.30000001192092896f32,-0.11999999731779099f32,0.5f32,0.5999999642372131f32,0.699999988079071f32,0.7999999523162842f32,0.17999999225139618f32,1.0f32,-0.32999998331069946f32,0.47999998927116394f32,0.5199999809265137f32]);
    assert_eq!(second[3].as_ref().unwrap().requires_grad(),true);
    close(second[4].as_ref().unwrap(),&[-0.3199999928474426f32,-1.7599999904632568f32,-1.649999976158142f32]);
    assert_eq!(second[4].as_ref().unwrap().requires_grad(),true);
    let mut total=second[0].as_ref().unwrap().sum();
    for derivative in &second[1..] {total=total.add(&derivative.as_ref().unwrap().sum()).unwrap();}
    let third=total.vjp_wrt_optional(&[&g,&x,&w,&a,&b],&Tensor::scalar(1.),false).unwrap();
    close(third[0].as_ref().unwrap(),&[-1.2999999523162842f32,1.0f32,-1.5000001192092896f32,1.0f32,1.0f32,1.0f32,1.0f32,-0.10000000894069672f32,1.0f32,-0.8999999761581421f32,1.100000023841858f32,0.7000000476837158f32]);
    close(third[1].as_ref().unwrap(),&[0.0f32,0.0f32,0.699999988079071f32,0.0f32,0.0f32,0.0f32,0.0f32,0.699999988079071f32,0.0f32,1.3999998569488525f32,1.8999998569488525f32,2.0f32]);
    close(third[2].as_ref().unwrap(),&[0.6000000238418579f32,1.3999998569488525f32,3.4000000953674316f32]);
    close(third[3].as_ref().unwrap(),&[0.4000000059604645f32,1.0f32,0.09999996423721313f32,1.0f32,1.0f32,1.0f32,1.0f32,1.100000023841858f32,1.0f32,0.7999998927116394f32,1.5999999046325684f32,1.6999999284744263f32]);
    close(third[4].as_ref().unwrap(),&[0.19999998807907104f32,-0.8000001907348633f32,1.1999999284744263f32]);
    assert!(g.grad().is_none()&&x.grad().is_none()&&w.grad().is_none()&&a.grad().is_none()&&b.grad().is_none());
}
